  "Alla blänker! Tjuven gillar bara saker som glittrar. Och den kan flyga …": "Tất cả đều sáng bóng! Tên trộm chỉ thích đồ lấp lánh. Và nó biết bay …",
  "Alla börjar i en rostig husvagn ute i förorten. Tjäna pengar på stadens jobb, köp mat så du orkar, klä dig snyggt – och spara ihop till en bättre bostad hos bostadsbyrån!": "Ai cũng bắt đầu trong một chiếc xe cắm trại cũ gỉ ở ngoại ô. Kiếm tiền từ các công việc trong thành phố, mua đồ ăn để có sức, ăn mặc thật đẹp – và để dành tiền thuê chỗ ở tốt hơn ở văn phòng Nhà Đất!",
  "Alla dagens djur är sålda – nya kommer i morgon!": "Thú cưng hôm nay đã bán hết – ngày mai sẽ có bé mới!",
