  "Alla fyra livsmålen på <b>{0} dagar</b> – från en rostig husvagn till ett riktigt liv!": "Đạt cả bốn mục tiêu cuộc sống trong <b>{0} ngày</b> – từ chiếc xe cắm trại cũ kỹ đến một cuộc sống thật sự!",
