  "Dra djuret dit du vill ha det – också in i ett annat rum. Klappa det, lek med det eller lägg det i lådan.": "Kéo con vật đến chỗ bạn muốn – cả sang phòng khác. Vuốt ve nó, chơi với nó hoặc cất nó vào hộp.",
  "Dra figuren dit du vill ha den – släpp den på en soffa, stol eller säng så sätter den sig.": "Kéo nhân vật đến chỗ bạn muốn – thả lên sofa, ghế hoặc giường là bạn ấy ngồi xuống.",
