  "Dra saken dit du vill ha den – upp på ett bord, till en figur som håller den, eller till ett djur som leker med den.": "Kéo món đồ đến chỗ bạn muốn – lên bàn, đến một nhân vật để cầm, hoặc đến một con vật để nó chơi.",
