  "Du behöver tjäna <b>{0}</b> till – ungefär <b>{1} pass</b> (≈ {2} per pass).": "Bạn cần kiếm thêm <b>{0}</b> – khoảng <b>{1} ca</b> (≈ {2} mỗi ca).",
