  "Du får <b>{0}</b> nu. Betala tillbaka <b>{1}</b> (lånet + {2} % ränta) senast <b>{3}</b> så får du tillbaka möbeln. Annars behåller pantbanken den.": "Bạn nhận <b>{0}</b> bây giờ. Trả lại <b>{1}</b> (tiền vay + {2} % lãi) chậm nhất <b>{3}</b> thì bạn lấy lại món đồ. Không thì tiệm cầm đồ giữ nó.",
  "Du får den i handen och sätter dig vid bistroborden här bredvid – mättheten kommer medan du äter.": "Bạn cầm món ăn và ngồi xuống bàn bistro ngay bên cạnh – bạn sẽ no dần khi ăn.",
  "Du får en bricka och sätter dig vid ett ledigt bord. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Bạn nhận một khay và ngồi vào bàn trống. Độ no và năng lượng tăng dần khi bạn ăn – chỉ khi bạn ngồi thôi!",
  "Du får maten på en bricka och sätter dig vid ett bord eller i fönstret med utsikt över havet. Mättnaden och energin kommer medan du äter – och när allt är uppätet blir du gladare!": "Bạn nhận đồ ăn trên khay và ngồi ở bàn hoặc bên cửa sổ nhìn ra biển. Bạn no dần và có thêm sức trong lúc ăn – ăn hết là bạn vui hơn!",
  "Du får maten på en bricka och sätter dig vid ett ledigt bord eller vid fönstret. Mättnaden och energin kommer medan du äter – bara när du sitter!": "Bạn nhận đồ ăn trên khay rồi ngồi vào bàn trống hoặc cạnh cửa sổ. Độ no và năng lượng tăng dần trong lúc bạn ăn – chỉ khi bạn ngồi thôi!",
