  "En sak värd minst 150 kr: ett plagg, en möbel eller ett kortpaket. Slumpas bland det du inte har – alla lika troliga.": "Một món đồ đáng giá ít nhất 150 đồng: một bộ quần áo, một món nội thất hoặc một gói thẻ. Chọn ngẫu nhiên trong những thứ bạn chưa có – món nào cũng có cơ hội như nhau.",
  "En skata": "Chim ác là",
  "En skata! Skator samlar på blanka saker och gömmer dem i sitt bo. Men var bor den?": "Chim ác là! Ác là thích sưu tầm đồ sáng bóng và giấu trong tổ. Nhưng nó sống ở đâu?",
  "En skata, säger du? Ha! Den har varit här också – den försökte ta en ring från disken.": "Chim ác là à? Ha! Nó cũng từng đến đây – nó định lấy một chiếc nhẫn trên quầy đấy.",
  "En skata?! Och den bytte bort den mot en knapp? Vilken historia!": "Chim ác là á?! Rồi nó đổi lấy một chiếc cúc? Chuyện gì mà hay thế!",
  "En skiva rostbröd som alltid är glad.": "Một lát bánh mì nướng lúc nào cũng vui vẻ.",
  "En skraplott kostar <b>{0} kr</b>. Skrapa fram sex belopp – <b>tre lika</b> och du vinner beloppet: 100, 500 eller 1 000 kr!": "Một vé cào giá <b>{0} đ</b>. Cào ra sáu số tiền – <b>ba số giống nhau</b> là bạn thắng số tiền đó: 100, 500 hoặc 1 000 đ!",
  "En skål från marknaden": "Cái bát từ chợ",
  "En sorts aktie": "Một loại cổ phiếu",
  "En spaghetti för två på Söders mysigaste trattoria.": "Spaghetti cho hai người ở quán trattoria ấm cúng nhất Phố Cổ.",
  "En strut popcorn": "Một túi bỏng ngô",
  "En svartvit fjäder": "Một chiếc lông đen trắng",
  "En svartvit fjäder med blågrön glans … Var kommer den ifrån, tror du?": "Một chiếc lông đen trắng ánh xanh lục … Bạn nghĩ nó từ đâu ra?",
  "En säck räcker till {0} skålar mat. Hemma: klicka på säcken så bär du den, klicka sen på skålen så häller du upp.": "Một bao đủ cho {0} bát. Ở nhà: bấm vào bao để cầm lên, rồi bấm vào bát để đổ ra.",
  "En säng, ett kylskåp och en garderob. Men det är ditt.": "Một cái giường, một tủ lạnh và một tủ quần áo. Nhưng là của bạn.",
  "En söt rosett mitt på huvudet.": "Một chiếc nơ xinh ngay giữa đầu.",
  "En tappad pärla": "Một hạt ngọc bị rơi",
  "En turkos glittrig kattrumpa med pärlor inuti. Kläm – svansen reser sig!": "Mông mèo màu ngọc lam lấp lánh, có hạt bên trong. Bóp đi – đuôi dựng lên!",
  "En tv. Den funkar!": "Một cái tivi. Nó còn chạy!",
  "En virvel på vägen": "Có một vòng xoáy giữa đường",
  "En ångad bulle med små pandaöron.": "Một chiếc bánh bao hấp có đôi tai gấu trúc nhỏ xíu.",
