  "Entré till Vattenlandet hela dagen: <b>{0}</b>. Kanorna, vågpoolen och solstolarna ingår. Du har {1}.": "Vé vào Công viên nước cả ngày: <b>{0}</b>. Gồm cầu trượt, hồ tạo sóng và ghế tắm nắng. Bạn có {1}.",
  "Esc stänger": "Esc để đóng",
  "Espresson får mig att vakna!": "Espresso làm mình tỉnh hẳn!",
  "Ett RAM-minne": "Một thanh RAM",
  "Ett barn har tappat bort sin mamma i lokalen. Vad gör du?": "Một bạn nhỏ bị lạc mẹ trong tiệm. Bạn làm gì?",
  "Ett berg av räkor på en skiva bröd. Måsarna tittar avundsjukt.": "Cả núi tôm trên một lát bánh mì. Bọn hải âu nhìn thèm thuồng.",
  "Ett blått hus med vita knutar. Katten Misse sover på verandan.": "Một ngôi nhà màu xanh dương với góc tường trắng. Mèo Mướp ngủ trên hiên.",
  "Ett bo fullt av glitter? Och mina pärlor där? Haha, vilken skata!": "Một cái tổ đầy đồ lấp lánh? Có cả hạt ngọc của mình trong đó? Haha, con ác là này thật là!",
  "Ett brädspel för hela familjen – knuffa hem dina pjäser!": "Trò chơi bàn cờ cho cả nhà – đá ngựa bạn khác và đưa ngựa của bạn về chuồng!",
  "Ett byte! Skator vill ha något blankt i stället. Nova på BLING BLING har säkert något glittrigt …": "Đổi đồ! Chim ác là sẽ muốn một món sáng bóng khác. Nova ở BLING BLING chắc có gì đó lấp lánh …",
  "Ett dagskort kostar {0} och gäller hela dagen. Ett pass tar 10 energi.": "Vé ngày giá {0} và dùng được cả ngày. Một buổi tập tốn 10 năng lượng.",
  "Ett djur som blir klappat och lekt med varje dag samarbetar bäst i ringen.": "Bé nào được vuốt ve và chơi cùng mỗi ngày sẽ phối hợp tốt nhất trong vòng thi.",
  "Ett djur som varit på hälsokoll den senaste veckan får extra poäng för hälsan på utställningen!": "Bé nào được khám sức khỏe trong tuần vừa qua sẽ được thêm điểm sức khỏe ở cuộc thi!",
  "Ett extra tangentbord": "Thêm một bàn phím",
  "Ett falurött hus på landet med ladugård, hönsgård och hagar fulla av djur. Bli bonde!": "Một ngôi nhà mái ngói đỏ ở làng quê, có chuồng bò, chuồng gà và bãi cỏ đầy thú. Làm nông dân thôi!",
  "Ett fjäderspö kostar 20 kr – katterna blir tokiga i det!": "Một cần câu lông vũ giá 20 đ – mèo mê nó lắm!",
  "Ett flygplan": "Một chiếc máy bay",
  "Ett gammalt landshövdingehus – stenvåning nertill och två våningar trä ovanpå. Här bor andra.": "Một căn nhà phố cổ – tầng dưới xây bằng đá, hai tầng gỗ ở trên. Người khác sống ở đây.",
  "Ett gott val!": "Chọn hay lắm!",
  "Ett grönt hus med blå dörr. Här bor andra.": "Một ngôi nhà màu xanh lá có cửa xanh dương. Nhà này có người khác ở.",
  "Ett gult hus med studsmatta i trädgården. Här bor andra.": "Một ngôi nhà màu vàng có bạt nhún trong vườn. Nhà này có người khác ở.",
  "Ett gult hus med vita knutar. Här bor andra.": "Một ngôi nhà màu vàng có góc tường trắng. Người khác sống ở đây.",
  "Ett hus med balkonger fulla av växter. Här bor andra.": "Một ngôi nhà có ban công đầy cây xanh. Người khác sống ở đây.",
  "Ett hus med en liten trädgård bakom. Här bor andra.": "Một ngôi nhà có khu vườn nhỏ phía sau. Người khác sống ở đây.",
  "Ett hus vid kajen med båtar utanför. Här bor andra.": "Một ngôi nhà bên bến sông, có thuyền đậu phía trước. Người khác sống ở đây.",
  "Ett kontokort": "Thẻ ngân hàng",
  "Ett kontoutdrag, tack.": "Cho tôi sao kê tài khoản nhé.",
  "Ett landshövdingehus med blomlådor i varje fönster. Här bor andra.": "Một căn nhà cổ có bồn hoa ở mỗi cửa sổ. Người khác sống ở đây.",
  "Ett landshövdingehus med cyklar på gården. Här bor andra.": "Một căn nhà cổ có xe đạp trong sân. Người khác sống ở đây.",
  "Ett litet lok i trä – precis som det på lekmattan.": "Một đầu tàu nhỏ bằng gỗ – giống hệt cái trên thảm chơi.",
  "Ett pass tar 4 timmar. Chefen betalar direkt efter passet.": "Một ca dài 4 tiếng. Quản lý trả tiền ngay sau ca.",
  "Ett pass tar tio energi. Trött? Ät något eller sov först, annars blir lyften sluddriga.": "Một buổi tập tốn mười năng lượng. Mệt à? Ăn gì đó hoặc ngủ trước đã, không thì nâng tạ sẽ lóng ngóng lắm.",
  "Ett rosa hus med hängmatta. Familjen Rosén har garageloppis på uppfarten.": "Một ngôi nhà hồng có võng. Gia đình Hồng bày bán đồ cũ ngay trước nhà xe.",
  "Ett rosa hus med hängmatta. Här bor andra.": "Một ngôi nhà màu hồng có võng. Nhà này có người khác ở.",
  "Ett rum och kök på sjunde våningen i Betongvägen 1. Hissen går ibland.": "Một phòng và bếp ở tầng bảy, số 1 Đường Bê Tông. Thang máy lúc chạy lúc không.",
  "Ett rött hus med äppelträd. Barnen Berg säljer lemonad vid grinden.": "Một ngôi nhà đỏ có cây táo. Mấy bạn nhỏ nhà Sơn bán nước chanh ở cổng.",
  "Ett rött hus med äppelträd. Här bor andra.": "Một ngôi nhà màu đỏ có cây táo. Nhà này có người khác ở.",
  "Ett rött trähus med en katt i fönstret. Här bor andra.": "Một ngôi nhà gỗ màu đỏ có con mèo bên cửa sổ. Người khác sống ở đây.",
  "Ett sjunde rum i Dockskåpet: tronsalen med tron, kristallkrona, rustning, fontän, himmelssäng, facklor och en drake – för alltid.": "Phòng thứ bảy trong Nhà búp bê: phòng ngai vàng có ngai vàng, đèn chùm pha lê, áo giáp, đài phun nước, giường màn trướng, đuốc và một con rồng – của bạn mãi mãi.",
  "Ett sjätte rum i Dockskåpet: husets baksida med gräsmatta, pool, gunga, studsmatta, grill, äppelträd och mer – för alltid.": "Phòng thứ sáu trong Nhà búp bê: sân sau của ngôi nhà có bãi cỏ, hồ bơi, xích đu, bạt nhún, bếp nướng, cây táo và nhiều thứ khác – của bạn mãi mãi.",
  "Ett skohorn – så glider hälen i utan att trampa ner skon. 🥄": "Cây đón gót – để gót chân trượt vào mà không giẫm lên giày. 🥄",
  "Ett smalt hus med en grön dörr. Här bor andra.": "Một căn nhà ống hẹp có cửa màu xanh lá. Người khác sống ở đây.",
  "Ett snurr kostar {0}. Vinster: kortpaket, pengar och godis!": "Một lượt quay giá {0}. Giải thưởng: gói thẻ, tiền và kẹo!",
  "Ett sorts schema för rasterna": "Một kiểu lịch giờ nghỉ",
  "Ett tips: gå till trimmaren först! En nygjord frisyr ger mest poäng för pälsen.": "Mẹo nhỏ: ghé tiệm tỉa lông trước nhé! Kiểu lông mới làm giúp bộ lông được nhiều điểm nhất.",
  "Ett varv på Pricken": "Một vòng cưỡi Đốm",
  "Ett varv på karusellen kostar <b>{0} kr</b>. Välj häst!": "Một vòng ngựa gỗ giá <b>{0} đ</b>. Chọn ngựa đi!",
  "Ett varv på ponnyn Pricken kostar <b>{0}</b>. Han går lugnt – håll i sadeln!": "Một vòng trên lưng ngựa nhỏ Đốm giá <b>{0}</b>. Chú đi chậm rãi – nhớ bám chặt yên nhé!",
  "Ett vitt hus med garage. Bilen är alltid nytvättad.": "Một ngôi nhà màu trắng có nhà xe. Xe ô tô lúc nào cũng sạch bóng.",
  "Ett vitt hus med garage. Vivi söker någon som klipper gräset.": "Một ngôi nhà trắng có nhà xe. Cô Thu cần người cắt cỏ.",
