  "I mobilen 📱 nere till höger finns kartan, kompisarna och livsmålen. På kartan hittar du fler jobb, och under Livsmål ser du vad du sparar till. Ju mer du jobbar, desto bättre betalt.": "Trong điện thoại 📱 ở góc dưới bên phải có bản đồ, bạn bè và mục tiêu sống. Trên bản đồ, bạn tìm thấy thêm việc làm, và trong Mục tiêu sống, bạn thấy mình đang để dành tiền cho gì. Càng làm nhiều, lương càng cao.",
  "I mobilen 📱 nere till höger hittar du alla jobb under Jobb, vägen hem under Hem, och kartan, kompisarna och livsmålen. Ju mer du jobbar, desto bättre betalt.": "Trong điện thoại 📱 ở góc dưới bên phải, bạn tìm thấy mọi việc làm trong Việc làm, đường về nhà trong Nhà, cùng bản đồ, bạn bè và mục tiêu sống. Càng làm nhiều, lương càng cao.",
