  "Kronan på kattstatyn i Tassbacken har försvunnit. Ett nytt kapitel varje dag – kan du lösa mysteriet?": "Vương miện trên tượng mèo ở Đồi Cún Mèo đã biến mất. Mỗi ngày một chương mới – bạn có giải được bí ẩn không?",
