  "Välj": "Chọn",
  "Välj din avatar eller skapa en ny.": "Chọn nhân vật của bạn hoặc tạo nhân vật mới.",
  "Välj en bok. Att läsa ut den tar en timme och ger en utbildningspoäng första gången.": "Chọn một cuốn sách. Đọc xong mất một giờ và cho bạn một điểm học vấn ở lần đầu.",
  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Chọn một gói hạt giống. Tưới luống mỗi ngày – hai ngày không tưới là cây héo. Thu hoạch sẽ vào tủ bếp.",
  "Välj en häst.": "Chọn một con ngựa.",
  "Välj en låt – den går hemma tills du stänger av eller lägger dig. Alla låtar i Pixelstaden finns här.": "Chọn một bài – bài hát sẽ phát ở nhà đến khi bạn tắt hoặc đi ngủ. Mọi bài hát ở Thành phố Pixel đều có ở đây.",
  "Välj en möbel först": "Chọn một món đồ trước đã",
  "Välj en ny frisyr eller färg först.": "Chọn kiểu tóc hoặc màu mới trước đã.",
  "Välj en ny frisyr eller hårfärg – förhandsbilden visar hur det blir på dig.": "Chọn kiểu tóc hoặc màu tóc mới – ảnh xem trước cho thấy bạn sẽ trông thế nào.",
  "Välj ett belopp.": "Chọn một số tiền.",
  "Välj ett märke": "Chọn một hình dán",
  "Välj ett ställe på kartan.": "Chọn một nơi trên bản đồ.",
  "Välj färg – en ballong kostar {0}. Den följer med dig på tivolit hela dagen!": "Chọn màu đi – một quả bóng bay giá {0}. Bóng sẽ theo bạn đi khắp khu vui chơi cả ngày!",
  "Välj hur högt du siktar i varje mål. Du har klarat livet i Pixelstaden när alla fyra är nådda samtidigt.": "Chọn mức bạn nhắm tới cho từng mục tiêu. Bạn chinh phục cuộc sống ở Thành phố Pixel khi đạt cả bốn cùng một lúc.",
  "Välj hur mycket du vill sätta in.": "Chọn số tiền bạn muốn gửi vào.",
  "Välj hur mycket du vill ta ut.": "Chọn số tiền bạn muốn rút ra.",
  "Välj kana. Trapporna upp är branta – håll i räcket.": "Chọn cầu trượt. Cầu thang lên dốc lắm – vịn tay vịn nhé.",
  "Välj någon i laget – eller skriv ett eget förnamn och nummer.": "Chọn một bạn trong đội – hoặc tự viết tên và số áo riêng.",
  "Välj något från menyn först!": "Chọn một món trong thực đơn trước đã!",
  "Välj något i butiken så slår jag in det!": "Chọn một món trong cửa hàng là mình gói cho bạn!",
  "Välkommen fram!": "Chào mừng bạn đã tới nơi!",
  "Välkommen in! Värm upp lite först så går lyften lättare.": "Mời vào! Khởi động một chút trước để nâng tạ dễ hơn nhé.",
  "Välkommen in! ✨": "Mời vào! ✨",
  "Välkommen ombord! Vad får det lov att vara?": "Chào mừng lên tàu! Bạn muốn dùng gì?",
  "Välkommen till BLIXT!": "Chào mừng đến CHỚP!",
  "Välkommen till Biblioteket! Ta en bok från hyllan och sätt dig vid ett bord. Varje utläst bok ger en utbildningspoäng.": "Chào mừng đến Thư viện! Lấy một cuốn sách trên kệ rồi ngồi vào bàn nhé. Mỗi cuốn đọc xong cho bạn một điểm học vấn.",
  "Välkommen till Bio Pixel!": "Chào mừng đến Rạp Pixel!",
  "Välkommen till Gamla stan! Huset bakom mig är från 1699 – titta på årtalet i gaveln.": "Chào mừng bạn đến Thành Cổ! Ngôi nhà sau lưng mình xây năm 1699 – nhìn con số trên đầu hồi kìa.",
  "Välkommen till Klipp & Klo! Har du ett husdjur så gör vi det jättefint här. ✂️": "Chào mừng đến Kéo & Móng! Nếu bạn có thú cưng, tụi mình sẽ làm bé thật xinh ở đây. ✂️",
  "Välkommen till Klipp & Klo! ✂️ Klicka på trimbordet så fixar vi ditt djur.": "Chào mừng đến Kéo & Móng! ✂️ Bấm vào bàn tỉa lông, tụi mình sẽ làm đẹp cho bé cưng của bạn.",
  "Välkommen till Kurr! ☕ Fika vid disken – och klappa gärna katterna, de älskar det.": "Chào mừng đến Gừ Gừ! ☕ Gọi đồ ăn uống ở quầy – và cứ vuốt ve các bé mèo, chúng thích lắm.",
  "Välkommen till Museet! Titta på föremålen – skyltarna berättar. När du sett tre stycken får du ta quizet hos mig.": "Chào mừng bạn đến Bảo tàng! Hãy xem các hiện vật – bảng tên sẽ kể cho bạn nghe. Xem xong ba món thì đến chỗ chú làm câu đố nhé.",
  "Välkommen till Pixel Gym! Hantlarna och boxsäcken ger STYRKA, gruppasset KONDITION och dansgolvet RYTM.": "Chào mừng đến Pixel Gym! Tạ tay và bao cát cho SỨC MẠNH, lớp tập cho THỂ LỰC và sàn nhảy cho NHỊP ĐIỆU.",
  "Välkommen till Pixelbanken!": "Chào mừng đến Pixelbank!",
