  "Välkommen till {0}! Första föreläsningen är i Aula 1 – sätt dig i en ledig bänk.": "Chào mừng đến với {0}! Buổi học đầu tiên ở Giảng đường 1 – ngồi vào một chỗ trống nhé.",
