  "🔒 Pengarna på banken är trygga. Hyran dras först från fickan – räcker den inte tar banken resten från sparkontot, så du slipper hamna i skuld.": "🔒 Tiền gửi ngân hàng rất an toàn. Tiền thuê trừ vào tiền trong túi trước – nếu không đủ, ngân hàng lấy phần còn lại từ tài khoản tiết kiệm, nên bạn không bị mắc nợ.",
  "🔒 Salongen är låst tills bion öppnar {0}.": "🔒 Phòng chiếu khóa cho tới khi rạp mở lúc {0}.",
  "🔒 Stängt – pantbanken har öppet {0}–{1}.": "🔒 Đóng cửa – tiệm cầm đồ mở cửa {0}–{1}.",
  "🔒 Tryggt: pengarna på banken rörs bara av hyran, och bara när fickan inte räcker (autogiro). Räntan räknas på högst {0}.": "🔒 An toàn: tiền trong ngân hàng chỉ bị trừ để trả tiền nhà, và chỉ khi tiền trong túi không đủ (tự động trừ). Tiền lãi chỉ tính trên tối đa {0}.",
  "🔒 Valvet! Guldtackor, säckar och bankfack – och någonstans därinne mina {0} kr.": "🔒 Két sắt! Vàng thỏi, bao tiền và hộp ký gửi – và đâu đó trong ấy có {0} đ của mình.",
  "🔒 gör en felfri runda i {0} först": "🔒 hoàn thành {0} không lỗi trước đã",
  "🔒 {0} fler – köps i klädaffären och i stans nya butiker": "🔒 Thêm {0} món – mua ở tiệm quần áo và các cửa hàng mới trong phố",
  "🔒 {0} har du på dig men äger inte – byter du bort den finns den i klädaffären.": "🔒 Bạn đang mặc {0} nhưng chưa sở hữu – nếu đổi sang món khác, bạn sẽ tìm thấy nó ở tiệm quần áo.",
  "🔒 {0} har stängt för i dag – öppnar {1} i morgon.": "🔒 {0} đã đóng cửa hôm nay – mai mở lúc {1}.",
