  "🔔 Notiserna är av. Slå på dem så säger mobilen till kl. 7 och kl. 19 när en present väntar!": "🔔 Thông báo đang tắt. Bật lên để điện thoại báo lúc 7 giờ và 19 giờ khi có quà đang chờ!",
