  "🔥 Du håller händerna över elden. Vantarna ångar. +4 ⚡": "🔥 Bạn hơ tay trên ngọn lửa. Găng tay bốc hơi nghi ngút. +4 ⚡",
  "🔥 Du lägger i ett vedträ. Kaminen sprakar och värmen sprider sig i stugan. +6 ⚡": "🔥 Bạn bỏ thêm một thanh củi. Lò sưởi lách tách và hơi ấm lan khắp nhà. +6 ⚡",
  "🔥 Elden sprakar. Det är den varmaste platsen i hela Gamla stan.": "🔥 Lửa reo tí tách. Đây là chỗ ấm nhất cả Thành Cổ.",
  "🔥 Håll i elden": "🔥 Giữ trên lửa",
  "🔥 Kakelugnen är varm. Gösta har bästa platsen framför den.": "🔥 Lò sưởi ấm áp lắm. Mập giành được chỗ đẹp nhất ngay phía trước.",
  "🔥 Kaminen brinner fint. Kaffepannan puttrar på plattan.": "🔥 Lò sưởi cháy đều. Ấm cà phê sôi lục bục trên bếp.",
  "🔥 Rökeriet: makrillen hänger över alspånen. Den rökta fisken säljs i marknadshallen.": "🔥 Lò hun: cá thu treo trên lớp mùn gỗ cháy âm ỉ. Cá hun khói được bán ở nhà chợ.",
