  "🔥 {0} dagar i rad – en STOR LÅDA väntar i mobilen 📱": "🔥 {0} ngày liền – một HỘP LỚN đang chờ trong điện thoại 📱",
  "🔥 {0} dagar i rad – en mellanlåda väntar i mobilen 📱": "🔥 {0} ngày liền – một hộp vừa đang chờ trong điện thoại 📱",
