  "🔧 jobbar på bilverkstaden": "🔧 đang làm ở gara ô tô",
  "🔨 Bygga: dra möbler från lådan, flytta, vrid och måla dem.": "🔨 Xây: kéo đồ nội thất ra từ hộp, di chuyển, xoay và sơn màu.",
