  "🔪 Kött eller kyckling – båda har snurrat sen i morse!": "🔪 Thịt bò hay thịt gà – cả hai đã quay từ sáng sớm!",
  "🔭 Bara måsar … och en gammal gummistövel som flyter förbi.": "🔭 Chỉ có hải âu … và một chiếc ủng cao su cũ trôi ngang qua.",
  "🔭 Du ser ända bort till fyren. Inga delfiner just nu.": "🔭 Bạn nhìn thấy tận ngọn hải đăng. Giờ chưa có cá heo.",
  "🔭 Du spanar ut över vattnet … där! Något stort rör sig under ytan!": "🔭 Bạn nhìn ra mặt nước … kia! Có gì đó to lắm đang bơi dưới nước!",
  "🔭 En segelbåt långt ute. Vattnet glittrar i solen.": "🔭 Một chiếc thuyền buồm ở xa xa. Mặt nước lấp lánh dưới nắng.",
  "🔭 Fiskarna hoppar – men ingen delfin den här gången.": "🔭 Cá nhảy lên khỏi nước – nhưng lần này không có cá heo.",
  "🕒 Klockan är {0}. Banken har öppet {1}–{2} – bankomaten dygnet runt.": "🕒 Bây giờ là {0}. Ngân hàng mở cửa {1}–{2} – cây ATM thì suốt ngày đêm.",
  "🕒 Klockan är {0}. Banken har öppet {1}–{2}.": "🕒 Bây giờ là {0}. Ngân hàng mở cửa {1}–{2}.",
  "🕒 Klockan är {0}:{1}. Bostadsbyrån har öppet 07–20.": "🕒 Bây giờ là {0}:{1}. Văn phòng Nhà Đất mở cửa 07–20.",
  "🕰️ En moraklocka för 3 500 kr. Den tickar högt.": "🕰️ Một cái đồng hồ quả lắc giá 3.500 đ. Nó kêu tích tắc rất to.",
  "🕰️ Golvuret visar {0}. Det har tickat sedan 1699.": "🕰️ Đồng hồ chỉ {0}. Nó đã tích tắc từ năm 1699.",
  "🕰️ Tre klockor, tre tider. Bara den höga går rätt.": "🕰️ Ba cái đồng hồ, ba giờ khác nhau. Chỉ cái cao là chạy đúng.",
  "🕵️ Ett nytt kapitel i mysteriet väntar – öppna 🔍 Mysteriet i mobilen!": "🕵️ Một chương mới của bí ẩn đang chờ – mở 🔍 Bí ẩn trong điện thoại nhé!",
  "🕵️ Mysteriet är löst – kronan sitter på kattstatyn igen. Du är en mästerdetektiv!": "🕵️ Đã giải xong bí ẩn – vương miện đã về lại trên tượng mèo. Bạn là thám tử tài ba!",
  "🕵️ Mysteriet är löst!": "🕵️ Đã giải xong bí ẩn!",
  "🕵️ Något har hänt i Tassbacken! Öppna 🔍 Mysteriet i mobilen.": "🕵️ Có chuyện xảy ra ở Đồi Cún Mèo! Mở 🔍 Bí ẩn trong điện thoại.",
  "🕵️ Rätt!": "🕵️ Đúng rồi!",
  "🕵️ Svara": "🕵️ Trả lời",
  "🕵️ Vad tror du?": "🕵️ Bạn nghĩ sao?",
  "🕶️ Solglasögon för 49 kr. Snurrstället gnisslar.": "🕶️ Kính râm giá 49 đ. Giá xoay kêu cót két.",
  "🕹️ Gamingriggarna finns i fyra färger – klicka på en så väljer du modell.": "🕹️ Dàn máy game có bốn màu – bấm vào một cái để chọn mẫu.",
  "🖊️ Blanketter för insättning och uttag. Pennorna sitter fast i kedjor – ingen tar hem en bankpenna.": "🖊️ Giấy gửi tiền và rút tiền. Bút bị xích lại – không ai mang bút ngân hàng về nhà được.",
  "🖥️ Datorer, TV-apparater och spelkonsoler hamnar i förrådet hemma – ställ ut dem med 🛋️ Möblera.": "🖥️ Máy tính, TV và máy chơi game được đưa vào kho ở nhà – bày ra bằng 🛋️ Bày đồ.",
  "🖥️ Färdiga datorer": "🖥️ Máy tính lắp xong",
  "🖥️ bygger datorer på Pixel Data": "🖥️ đang lắp máy tính ở Tin học Pixel",
  "🖨️ Skrivaren surrar och spottar ut ett kontrakt. Fel namn – mäklaren suckar och trycker igen.": "🖨️ Máy in rè rè rồi nhả ra một bản hợp đồng. Sai tên – môi giới thở dài rồi in lại.",
  "🖼️ Albumet är fullt ({0} bilder) – ta bort några i 🖼️ Bilder först.": "🖼️ Album đầy rồi ({0} ảnh) – hãy xóa bớt trong 🖼️ Ảnh trước nhé.",
  "🖼️ Bilden gick inte att spara här.": "🖼️ Không lưu được ảnh ở đây.",
  "🖼️ Bilder": "🖼️ Ảnh",
  "🖼️ Du fick {0} på köpet – ställ ut den hemma med 🛋️ Möblera, så visar den dina egna designer!": "🖼️ Bạn được tặng kèm {0} – bày nó ở nhà bằng 🛋️ Bày đồ, nó sẽ trưng các mẫu thiết kế của chính bạn!",
  "🖼️ Fyren på Pixelskär – målad av Majas morfar.": "🖼️ Ngọn hải đăng trên Hòn Pixel – do ông ngoại của Mai vẽ.",
  "🗂️ Du spelar med samma figur i en annan flik – den här fliken är pausad. Rör den så tar den över igen.": "🗂️ Bạn đang chơi cùng nhân vật này ở một thẻ khác – thẻ này tạm dừng. Chạm vào đây để chơi tiếp ở thẻ này.",
  "🗂️ Kortkatalogen: en lapp för varje bok i huset, sorterade för hand. Porträttet är grundaren, Hedvig Bok.": "🗂️ Tủ mục lục: mỗi cuốn sách trong nhà có một tấm phiếu, xếp bằng tay. Bức chân dung là người sáng lập, bà Nguyễn Thị Sách.",
  "🗄️ Arkivskåpen är fulla av kontrakt. Nycklarna hänger i skåpet ovanför – en till varje bostad.": "🗄️ Tủ hồ sơ đầy ắp hợp đồng. Chìa khóa treo trong tủ phía trên – mỗi căn một chiếc.",
