  "🗑️ Ja, ta bort": "🗑️ Ừ, xóa đi",
  "🗑️ Skrynkliga utkast till annonser. \"Charmig etta med utsikt över ... parkeringen.\"": "🗑️ Bản nháp quảng cáo nhàu nát. \"Phòng trọ xinh xắn, nhìn ra ... bãi đỗ xe.\"",
  "🗑️ Ta bort": "🗑️ Xóa",
  "🗑️ Ta bort bilden?": "🗑️ Xóa ảnh này?",
  "🗣️ Du pratar": "🗣️ Bạn đang nói",
  "🗣️ Röst i närheten": "🗣️ Giọng nói gần đây",
  "🗺️ Entréplatsen – Sagolandet med karusellen, tekopparna och pariserhjulet – berg-och-dalbanan – radiobilarna – Spökgränd. Marknadsgatan går längs hela parken.": "🗺️ Quảng trường cổng vào – Xứ Cổ Tích với vòng quay ngựa gỗ, tách trà xoay và vòng quay khổng lồ – tàu lượn siêu tốc – xe điện đụng – Hẻm Ma. Phố Chợ chạy dọc cả khu vui chơi.",
  "🗺️ Kartan över Pixelstaden": "🗺️ Bản đồ Thành phố Pixel",
  "🗺️ Tryck på ett ställe: 🧭 en pil visar vägen dit, eller 🚕 ta en taxi.": "🗺️ Chạm vào một nơi: 🧭 mũi tên sẽ chỉ đường, hoặc 🚕 đi taxi.",
  "🗼 Fyren har lyst varje natt sedan 1890. Fyrvaktaren hette Hulda och bodde här med fjorton katter.": "🗼 Hải đăng đã sáng mỗi đêm từ năm 1890. Người giữ hải đăng tên là bà Thu, sống ở đây với mười bốn con mèo.",
  "🗼 Solöns fyr har lyst varje natt i över hundra år. Fyrvaktaren sägs ha en båt att hyra ut …": "🗼 Hải đăng Đảo Nắng đã sáng mỗi đêm hơn một trăm năm. Nghe nói người gác đèn có một chiếc thuyền cho thuê …",
  "🗽 Pixelstadens grundare. Varje vecka får den som skickar flest vänskapspresenter en egen guldstaty här.": "🗽 Người lập ra Thành phố Pixel. Mỗi tuần, ai gửi nhiều quà tình bạn nhất sẽ có một bức tượng vàng của riêng mình ở đây.",
  "🗽 Statyn föreställer {0} – förra veckans snällaste, som skickade {1} vänskapspresenter!": "🗽 Bức tượng này là {0} – người tốt bụng nhất tuần trước, đã gửi {1} món quà tình bạn!",
