  "😊 Lyckan är <b>{0}</b>. Gladare blir du av bion, att klappa och leka med djuren, kompisar, nya kläder, en ledig dag och ett fint hem. Många pass i rad och husvagnen gör dig nere.": "😊 Độ vui là <b>{0}</b>. Bạn vui hơn khi đi xem phim, vuốt ve và chơi với thú cưng, gặp bạn bè, có đồ mới, được nghỉ một ngày và có nhà đẹp. Làm nhiều ca liền nhau và ở xe cắm trại làm bạn buồn.",
